import struct,pathlib
GX_TC_TUPLES_SHARE_POINT_NUMBERS=0x8000
GX_TC_TUPLE_COUNT_MASK=0x0FFF
GX_TI_EMBEDDED_TUPLE_COORD=0x8000
GX_TI_INTERMEDIATE_TUPLE=0x4000
for p in pathlib.Path('repo-vul/src-vul/font-corpus').glob('*'):
 b=p.read_bytes()
 if len(b)<12: continue
 n=struct.unpack('>H',b[4:6])[0]; tabs={}
 for i in range(n):
  off=12+16*i
  if off+16<=len(b):
   tag=b[off:off+4].decode('latin1','ignore'); cs,to,ln=struct.unpack('>III',b[off+4:off+16]); tabs[tag]=(to,ln)
 if 'gvar' not in tabs: continue
 o,l=tabs['gvar']
 if o+20>len(b): continue
 maj,minr,axis,gcoord,coordoff,glyphcnt,flags,dataoff=struct.unpack('>HHHHHHI', b[o:o+20])
 offs=[]; pos=o+20
 if flags&1:
  for i in range(glyphcnt+1): offs.append(struct.unpack('>I',b[pos+4*i:pos+4*i+4])[0])
 else:
  for i in range(glyphcnt+1): offs.append(struct.unpack('>H',b[pos+2*i:pos+2*i+2])[0]*2)
 embeds=inter=active=0; examples=[]
 for gi in range(glyphcnt):
  s=o+dataoff+offs[gi]; e=o+dataoff+offs[gi+1]
  if e<=s or e>o+l or s+4>e: continue
  tc,otd=struct.unpack('>HH',b[s:s+4]); cnt=tc & GX_TC_TUPLE_COUNT_MASK; q=s+4
  active+=1
  for ti in range(cnt):
   if q+4>e: break
   tds,tidx=struct.unpack('>HH',b[q:q+4]); q+=4
   fl=[]
   if tidx&GX_TI_EMBEDDED_TUPLE_COORD:
    embeds+=1; fl.append('emb'); q += 2*axis
   if tidx&GX_TI_INTERMEDIATE_TUPLE:
    inter+=1; fl.append('inter'); q += 4*axis
   if fl and len(examples)<5: examples.append((gi,hex(tc),tds,hex(tidx),fl))
 print(p.name,'axis',axis,'glyphcnt',glyphcnt,'glyphvar',active,'emb',embeds,'inter',inter,'ex',examples[:3])
PY

